type Expr interface{ Pos() token.Pos }
type BinaryExpr struct {
    X     Expr        // left operand
    OpPos token.Pos
    Op    token.Token
    Y     Expr        // right operand
}
func (e *BinaryExpr) Pos() token.Pos { return e.X.Pos() }

